<script setup>defineProps({modelValue:[String,Number],label:String,hint:String,id:String,options:{default:()=>[]},disabled:Boolean});defineEmits(['update:modelValue'])</script><template><label class="select"><span v-if="label">{{label}}</span><select :id="id" :value="modelValue" :disabled="disabled" @change="$emit('update:modelValue',$event.target.value)"><option v-for="o in options" :key="o.value" :value="o.value">{{o.label}}</option></select><small>{{hint}}</small></label></template><style scoped>.select{display:grid;gap:7px;color:var(--text-secondary);font:600 13px/1.3 var(--font-core)}select{min-height:48px;padding:0 14px;border:1px solid var(--border-subtle);border-radius:var(--radius-md);background:var(--surface-primary);color:var(--text-primary);font:400 15px var(--font-core)}small{color:var(--text-muted);font-weight:400}</style>
